/* r7 = NZCV (bits 3..0), without changing the flags. */
.macro CAPTURE_FLAGS
    mov.w r7, #0
    bpl   4f
    orr.w r7, r7, #8
4:
    bne   5f
    orr.w r7, r7, #4
5:
    bcc   6f
    orr.w r7, r7, #2
6:
    bvc   7f
    orr.w r7, r7, #1
7:
.endm

/* Prints the 13 registers saved at DUMP, with \flags the NZCV saved after
 * them, and with \slot the 4 words at \slot. */
